  + '    };\n'
  + '    eventListener.register(el, callbackInternal);\n'
  + '    return () => {\n'
  + '      eventListener.unregister(el, callbackInternal);\n'
  + '    };\n'
  + '  }, [el, callback, eventListener]);\n'
  + '}\n'
  + '\n'
  + 'export { useClickOutside };\n'
