sourceCode['copy-ui-provider.tsx'] = ''
  + 'import { createContext, type FC, useEffect, useRef, useState } from "react";\n'
  + 'import { createStore, type StoreApi } from "zustand";\n'
  + '\n'
  + 'import { Toast } from "@/components/Toast";\n'
  + 'import { createJssState, type JssState } from "@/utils/jss";\n'
  + '\n'
  + 'import { ClickOutsideEventListener } from "./click-outside-event-listener";\n'
  + 'import { DEFAULT_THEME } from "./default-theme";\n'
  + 'import { MdxProvider } from "./mdx-provider";\n'
  + 'import type { Theme } from "./theme";\n'
  + 'import { useJss } from "./use-jss";\n'
  + '\n'
  + 'type CopyUiStoreState = {\n'
  + '  theme: Theme;\n'
  + '  mode: "light" | "dark";\n'
  + '\n'
  + '  jssState: JssState;\n'
  + '\n'
  + '  clickOutsideEventListener: ClickOutsideEventListener;\n'
  + '};\n'
  + '\n'
  + 'type CopyUiStoreActions = {\n'
  + '  setMode: (\n'
  + '    mode: "light" | "dark" | ((prevMode: "light" | "dark") => "light" | "dark"),\n'
  + '  ) => void;\n'
  + '};\n'
  + '\n'
  + 'type CopyUiStore = CopyUiStoreState & CopyUiStoreActions;\n'
  + '\n'
  + 'const CopyUiContext = createContext<StoreApi<CopyUiStore> | null>(null);\n'
  + '\n'
  + 'type CopyUiProviderProps = {\n'
  + '  children?: React.ReactNode;\n'
  + '};\n'
  + '\n'
  + 'const CopyUiProvider: FC<CopyUiProviderProps> = (props) => {\n'
  + '  const { children } = props;\n'
  + '\n'
  + '  const storeRef = useRef<StoreApi<CopyUiStore> | null>(null);\n'
  + '  if (storeRef.current === null) {\n'
  + '    storeRef.current = createStore<CopyUiStore>()((set) => ({\n'
  + '      theme: DEFAULT_THEME,\n'
  + '      mode: "light",\n'
  + '\n'
  + '      jssState: createJssState(),\n'
  + '\n'
  + '      clickOutsideEventListener: new ClickOutsideEventListener(),\n'
  + '\n'
  + '      setMode: (mode) => {\n'
  + '        set((state) => ({\n'
  + '          mode: typeof mode === "function" ? mode(state.mode) : mode,\n'
  + '        }));\n'
  + '      },\n'
  + '    }));\n'
  + '  }\n'
  + '\n'
  + '  return (\n'
  + '    <CopyUiContext.Provider value={storeRef.current}>\n'
  + '      <Toast.Context>\n'
  + '        <MdxProvider>{children}</MdxProvider>\n'
  + '        <Toast.Container />\n'
  + '      </Toast.Context>\n'
  + '      <JssSsrCss />\n'
  + '    </CopyUiContext.Provider>\n'
  + '  );\n'
  + '};\n'
  + '\n'
  + 'const JssSsrCss = () => {\n'
  + '  const jss = useJss();\n'
  + '  const css = jss.extractSsrCss();\n'
  + '  const [jssSsr, setJssSsr] = useState(true);\n'
  + '\n'
  + '  useEffect(() => {\n'
  + '    // Remove the style tag after hydration.\n'
  + '    setJssSsr(false);\n'
  + '  }, []);\n'
  + '\n'
  + '  if (!jssSsr) {\n'
  + '    return null;\n'
  + '  } else {\n'
  + '    return <style suppressHydrationWarning={true}>{css}</style>;\n'
  + '  }\n'
  + '};\n'
  + '\n'
  + 'CopyUiProvider.displayName = "CopyUiProvider";\n'
  + '\n'
  + 'export { CopyUiContext, CopyUiProvider };\n'
  ;

sourceCode['click-outside-event-listener.ts'] = ''
  + 'class ClickOutsideEventListener {\n'
  + '  stack: { el: HTMLElement; callback: (event: MouseEvent) => void }[] = [];\n'
  + '  handleClickOutside: (event: MouseEvent) => void;\n'
  + '\n'
  + '  constructor() {\n'
  + '    this.handleClickOutside = this.handleClickOutsideInner.bind(this);\n'
  + '  }\n'
  + '\n'
  + '  register(el: HTMLElement, callback: (event: MouseEvent) => void) {\n'
  + '    this.stack.push({ el, callback });\n'
  + '    if (this.stack.length === 1) {\n'
  + '      document.addEventListener("mousedown", this.handleClickOutside);\n'
  + '    }\n'
  + '  }\n'
  + '\n'
  + '  unregister(el: HTMLElement, callback: (event: MouseEvent) => void) {\n'
  + '    this.stack = this.stack.filter(\n'
  + '      (item) => item.el !== el && item.callback !== callback,\n'
  + '    );\n'
  + '    if (this.stack.length === 0) {\n'
  + '      document.removeEventListener("mousedown", this.handleClickOutside);\n'
  + '    }\n'
  + '  }\n'
  + '\n'
  + '  handleClickOutsideInner(event: MouseEvent) {\n'
  + '    const topEl = this.stack[this.stack.length - 1].el;\n'
  + '    console.log("handleClickOutside", {\n'
  + '      event,\n'
  + '      stack: this.stack,\n'
  + '      topEl,\n'
  + '      c: topEl.contains(event.target as Node),\n'
  + '    });\n'
  + '    if (topEl.contains(event.target as Node)) {\n'
  + '      return;\n'
  + '    }\n'
  + '    this.stack[this.stack.length - 1].callback(event);\n'
  + '  }\n'
  + '}\n'
  + '\n'
  + 'export { ClickOutsideEventListener };\n'
  ;

