sourceCode['use-mode.ts'] = ''
  + 'import { useContext } from "react";\n'
  + 'import { useStore } from "zustand";\n'
  + '\n'
  + 'import { CopyUiContext } from "./copy-ui-provider";\n'
  + '\n'
  + 'const useMode = () => {\n'
  + '  const copyUiContext = useContext(CopyUiContext);\n'
  + '  if (!copyUiContext) {\n'
  + '    throw new Error("useMode must be used within a CopyUiProvider");\n'
  + '  }\n'
  + '\n'
  + '  return useStore(copyUiContext, (state) => state.mode);\n'
  + '};\n'
  + '\n'
  + 'const useSetMode = () => {\n'
  + '  const copyUiContext = useContext(CopyUiContext);\n'
  + '  if (!copyUiContext) {\n'
  + '    throw new Error("useSetMode must be used within a CopyUiProvider");\n'
  + '  }\n'
  + '\n'
  + '  const setMode = useStore(copyUiContext, (state) => state.setMode);\n'
  + '\n'
  + '  return (\n'
  + '    mode: "light" | "dark" | ((prevMode: "light" | "dark") => "light" | "dark"),\n'
  + '  ) => {\n'
  + '    setMode(mode);\n'
  + '  };\n'
  + '};\n'
  + '\n'
  + 'export { useMode, useSetMode };\n'
  ;

